package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;
@Entity @Table(name="inventory_movement")public class MovimientoInventario{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="warehouse_id",nullable=false)private UUID almacenId;@Column(name="product_id",nullable=false)private UUID productoId;@Column(name="movement_date",nullable=false)private LocalDate fecha;@Column(nullable=false,precision=19,scale=4)private BigDecimal quantity;@Column(nullable=false,length=10)private String direction;@Column(name="movement_type",nullable=false,length=40)private String tipo;@Column(name="reference_type",nullable=false,length=40)private String tipoReferencia;@Column(name="reference_id",nullable=false)private UUID referenciaId;@Column(name="reversal_of_id")private UUID reversoDeId;@Column(name="created_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by",nullable=false)private UUID creadoPor;protected MovimientoInventario(){}public MovimientoInventario(UUID t,UUID e,UUID a,UUID p,LocalDate f,BigDecimal q,String d,String ti,String tr,UUID r,UUID re,UUID u){tenantId=t;empresaId=e;almacenId=a;productoId=p;fecha=f;quantity=q;direction=d;tipo=ti;tipoReferencia=tr;referenciaId=r;reversoDeId=re;creadoPor=u;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getEmpresaId(){return empresaId;}public UUID getAlmacenId(){return almacenId;}public UUID getProductoId(){return productoId;}public BigDecimal getCantidad(){return quantity;}public String getDireccion(){return direction;}public UUID getReferenciaId(){return referenciaId;}}
